import{_ as a}from"./chunks/EP.03-amis-editor.cZgSPNZU.js";import{_ as o,o as r,c as i,a2 as t}from"./chunks/framework.CnJ-JtFX.js";const b=JSON.parse('{"title":"EP.03 拖拽很爽，Schema 才是资产","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.03-amis-editor.md","filePath":"comics/EP.03-amis-editor.md","lastUpdated":1792683644000}'),l={name:"comics/EP.03-amis-editor.md"};function d(c,e,s,n,h,m){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="ep-03-拖拽很爽-schema-才是资产" tabindex="-1">EP.03 拖拽很爽，Schema 才是资产 <a class="header-anchor" href="#ep-03-拖拽很爽-schema-才是资产" aria-label="Permalink to &quot;EP.03 拖拽很爽，Schema 才是资产&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/03-amis-editor">guide/03-amis-editor</a></p></blockquote><p><img src="'+a+'" alt="EP.03 漫画"></p><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：运营一个月做五个活动页，每页改八轮文案，前端一半时间花在改配置上；运营想要有限的自主权。</li><li><strong>揭秘</strong>：码叔拆开编辑器：左侧物料、中间画布、右侧属性，三栏共用一棵 Schema 树；物料等于渲染器加编辑器插件。</li><li><strong>实证</strong>：像素酱注册 <code>order-status</code> 物料，用 <code>scaffold</code> 决定拖入时的初始 Schema，用 <code>panelControls</code> 决定运营能改什么，再把 Schema 保存为 JSON。</li><li><strong>结案</strong>：编辑器按需加载，运行时只带 amis；容器没高度会让画布直接消失，这是最常见的「空白」原因。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-给运营工具-不是给运营源码" tabindex="-1">第一格：给运营工具，不是给运营源码 <a class="header-anchor" href="#第一格-给运营工具-不是给运营源码" aria-label="Permalink to &quot;第一格：给运营工具，不是给运营源码&quot;">​</a></h3><p>运营的真实需求通常不是「任意改页面」，而是「在允许的范围内改文案、换组件、调属性」。如果直接给源码，风险不可控；如果什么都不给，所有改动都要排队。</p><p>编辑器的价值在于把「可改范围」建模成物料与属性面板。运营看到的是表单和拖拽，实际修改的是一棵受约束的 JSON 树。</p><p>对应正文：<a href="./../guide/03-amis-editor">从一个真实问题说起</a>。</p><h3 id="第二格-三栏与物料" tabindex="-1">第二格：三栏与物料 <a class="header-anchor" href="#第二格-三栏与物料" aria-label="Permalink to &quot;第二格：三栏与物料&quot;">​</a></h3><ul><li>左侧物料面板：已注册的渲染器加上对应的编辑器插件；</li><li>中间画布：把当前 Schema 渲染成页面，并提供选中、拖拽、删除；</li><li>右侧属性面板：根据选中节点的类型渲染表单，改完写回 Schema。</li></ul><p>拖拽的本质是对 JSON 树做插入、移动、删除，不是操作 DOM。理解这一点，才能解释「为什么保存下来的是 JSON，不是 HTML」。</p><h3 id="第三格-物料与持久化" tabindex="-1">第三格：物料与持久化 <a class="header-anchor" href="#第三格-物料与持久化" aria-label="Permalink to &quot;第三格：物料与持久化&quot;">​</a></h3><p>一个物料至少要有四部分：<code>rendererName</code>、<code>scaffold</code>、<code>previewSchema</code>、<code>panelControls</code>。缺了 <code>panelControls</code>，运营只能改源码；缺了 <code>scaffold</code>，拖进去是空节点。</p><p><code>localStorage</code> 持久化只适合演示。生产环境需要服务端存储、版本历史、发布状态与回滚能力。Schema 是资产，缓存不是。</p><h3 id="第四格-编辑器与运行时分离" tabindex="-1">第四格：编辑器与运行时分离 <a class="header-anchor" href="#第四格-编辑器与运行时分离" aria-label="Permalink to &quot;第四格：编辑器与运行时分离&quot;">​</a></h3><p>编辑器负责生产 Schema，运行时只消费 Schema。两者分离后，编辑器可以只在管理端按需加载，C 端或运营端只加载 <code>amis</code> 运行时，包体积与权限都能收敛。</p><p>本章的 lab 为了对比方便，把编辑和预览放在同一页；真实项目通常拆成两个入口。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>容器没有高度</strong>：amis-editor 绝对定位布局会塌陷，画布消失。</li><li><strong>只注册渲染器</strong>：物料面板找不到组件；只注册插件，预览显示未知组件。</li><li><strong><code>rendererName</code> 不一致</strong>：面板能展示，拖进画布却渲染失败。</li><li><strong>Monaco worker 未打包</strong>：控制台出现 <code>Unexpected token &#39;&lt;&#39;</code>，代码面板异常。</li><li><strong>把编辑器带进运行时</strong>：包体积暴涨，权限边界也会模糊。</li><li><strong>只存 <code>localStorage</code></strong>：换设备就丢，改坏无法回滚。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. 为什么一个自定义物料要注册两次？</b></summary><p>因为运行时和编辑器是两个消费方。<code>Renderer</code> 决定 Schema 在运行时如何渲染；<code>EditorPlugin</code> 决定物料面板如何展示、拖入时生成什么、属性面板能改什么。两者通过相同的 <code>type</code> / <code>rendererName</code> 对接，缺一不可。</p></details><details><summary><b>2. 编辑器和预览为什么要互斥挂载？</b></summary><p>两者都会创建 amis 数据域和 DOM 结构，同时挂载会争抢容器、重复请求、增加内存占用，还可能出现数据互相污染。用模式切换彻底卸载另一个，边界最清晰，也更容易排查问题。</p></details><details><summary><b>3. 生产环境的 Schema 治理至少需要哪些能力？</b></summary><p>至少需要服务端存储、版本号与历史、发布状态、回滚入口。进一步还需要 Schema 校验、按环境区分、灰度发布与权限控制。只有保存能力，没有版本与回滚，改坏一次就可能无法恢复。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../guide/03-amis-editor">第 03 章正文</a></li><li><a href="./../guide/04-formily-basics">第 04 章 · Formily 基础</a></li><li><a href="./../appendix/commands">各 lab 命令速查</a></li></ul>',27)])])}const f=o(l,[["render",d]]);export{b as __pageData,f as default};
